/**
 * Generate the standalone UPI intent-resolution test page.
 *
 * WHY A GENERATOR AND NOT A HAND-WRITTEN PAGE: the thing under test is
 * `buildUpiLinks`, not a re-implementation of it. If this page carried its own
 * copy of the URI construction, a passing test would prove that the copy
 * resolves — which is worth nothing, because the copy is not what the portal
 * sends residents. So the links are baked in at generation time by calling the
 * real builder, and `test/upi-testpage.test.js` asserts the generated bytes
 * still match it.
 *
 * WHY A SINGLE STATIC FILE WITH NO BACKEND: this page is meant to be deployed
 * as its own throwaway Cloudflare Pages project, NOT under the portal. Two
 * reasons, and neither is squeamishness:
 *
 *   * The portal's hostname carries the association's name, and so does every
 *     preview deployment beneath it. A test page whose URL announces the
 *     project is not an unbranded test page.
 *   * Serving it from the portal would put the tester through the real pay
 *     route, which writes `payment_intents` rows and flips a bill to
 *     `initiated` — surfacing a phantom "this resident is paying" in the
 *     committee's queue for a payment that was never attempted. Test traffic
 *     has no business in production D1.
 *
 * WHY THE PAYEE IS SUPPLIED AND NOT HARDCODED: the association's live VPA must
 * never appear here — a working link would put a real bill payment one tap away
 * from a tester who has no idea what they are looking at. But a payee that
 * cannot resolve is not free either. An app that opens and THEN errors is
 * ambiguous in the tester's retelling: "it didn't work" could mean resolution
 * failed, which is the thing under test, or that the registry lookup failed,
 * which is not. A VPA that resolves removes that ambiguity — a fully rendered
 * confirmation screen naming a payee proves the entire chain end to end.
 *
 * So the address is a parameter with an unresolvable default. Whoever runs the
 * test supplies one they own, and it stays out of this repository.
 *
 * WHY ONE RUPEE AND A NOTE THAT SAYS NOT TO PAY: a resolving payee means real
 * money CAN move, so two things cap the damage. The amount is trivial, and the
 * `tn` note is carried into the UPI app's own confirmation screen — the single
 * channel that reaches the tester at the moment of decision, after the browser
 * is gone. It is mitigation rather than a guarantee: not every app renders the
 * note. The amount is the part that does not depend on an app behaving.
 *
 * Usage:
 *   node scripts/gen-upi-testpage.mjs out.html --vpa you@bank --payee "Your Name"
 */

import { writeFileSync } from 'node:fs';
import { buildUpiLinks, ANDROID_PACKAGES } from '../functions/lib/upi.js';

/**
 * Deliberately unresolvable, and deliberately not a plausible-looking handle.
 *
 * `@invalid` is not a real PSP suffix, so no bank's registry can ever answer
 * for it. A typo'd version of a REAL handle would be worse than useless: it
 * might resolve to somebody else's account.
 */
export const TEST_VPA = 'nonexistent.testonly@invalid';
export const TEST_PAYEE = 'Link Test';
export const TEST_AMOUNT = 1;

/**
 * Rendered by the UPI app on its confirmation screen, in caps because it is the
 * last thing anyone reads before a real transfer. It is the only text this test
 * can put in front of the tester once the browser has handed off, so it says
 * the one thing that matters rather than describing the test.
 */
export const TEST_NOTE = 'TEST LINK - PLEASE DO NOT PAY';

/**
 * Every shape the portal can emit, each one its own row.
 *
 * The order matters and is not alphabetical: it runs from the least addressed
 * link to the most. `generic` is what Android is asked to resolve first in
 * production, and `intent-bare` is the shape whose failure mode (silent
 * fallback) is indistinguishable from a dead button — so both need to be
 * observed before any per-app result can be interpreted.
 */
export function linkRows(links) {
  const rows = [
    ['generic', 'upi:// — plain link, should raise the app chooser', links.generic],
    ['intent-bare', 'intent:// — no package named', links.intent],
  ];
  for (const app of Object.keys(ANDROID_PACKAGES)) {
    rows.push([`intent-${app}`, `intent:// — addressed to ${app}`, links.androidApps[app]]);
  }
  for (const app of Object.keys(ANDROID_PACKAGES)) {
    if (links[app]) rows.push([`scheme-${app}`, `${links[app].split('?')[0]} — direct scheme`, links[app]]);
  }
  // tez:// is not in the links object (only the first scheme per app ships),
  // but it is named in STATE.md as one of the shapes tested, so it is built
  // here from the same query string rather than being quietly dropped.
  const qs = links.generic.split('?')[1];
  rows.push(['scheme-tez', 'tez://upi/pay — legacy Google Pay scheme', `tez://upi/pay?${qs}`]);
  return rows;
}

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

/** The whole test page as one self-contained string — no imports, no backend. */
export function renderPage({ vpa = TEST_VPA, payee = TEST_PAYEE, now = new Date() } = {}) {
  const links = buildUpiLinks({
    vpa,
    payee,
    amount: TEST_AMOUNT,
    // The warning goes in through `flat` because that is the only route
    // `buildUpiLinks` offers to `tn`, and widening its signature for a test
    // would mean the page no longer exercises the builder the portal actually
    // ships. The stamp the builder glues on is left alone: it is noise here,
    // but stripping it would mean rebuilding the note by hand, which is the
    // duplication this whole script exists to avoid.
    flat: TEST_NOTE,
    now,
  });

  const rows = linkRows(links);
  const rowHtml = rows.map(([id, label, href]) => `
    <li class="row" data-id="${esc(id)}">
      <a class="tap" href="${esc(href)}">${esc(label)}</a>
      <div class="uri">${esc(href)}</div>
      <div class="verdict" data-verdict>not tried yet</div>
    </li>`).join('');

  return `<!doctype html>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Link check</title>
<style>
  :root { color-scheme: light dark; font: 16px/1.5 system-ui, sans-serif; }
  body { margin: 0; padding: 20px; max-width: 640px; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  .lead { color: #666; margin: 0 0 20px; }
  #warn { display: none; background: #b3261e; color: #fff; padding: 14px; border-radius: 8px; margin-bottom: 20px; }
  #warn.show { display: block; }
  ul { list-style: none; padding: 0; margin: 0; }
  .row { border: 1px solid #8883; border-radius: 10px; padding: 12px; margin-bottom: 12px; }
  .tap { display: block; font-weight: 600; text-decoration: none; color: #0b57d0; }
  .uri { font: 11px/1.4 ui-monospace, monospace; color: #888; word-break: break-all; margin: 6px 0; }
  .verdict { font-size: 14px; font-weight: 600; color: #888; }
  .verdict.opened { color: #146c2e; }
  .verdict.nothing { color: #b3261e; }
  #summary { width: 100%; min-height: 140px; margin-top: 8px; font: 12px ui-monospace, monospace; }
  button { font-size: 15px; padding: 10px 16px; border-radius: 8px; border: 1px solid #8886; background: transparent; color: inherit; }
</style>

<h1>Link check</h1>
<p class="lead">Tap each one in turn. After each tap, come back here and note what
you saw — then move to the next.</p>

<div id="warn">
  <strong>Open this in Chrome first.</strong> This page is running inside another
  app's built-in browser, which blocks these links on purpose. Results from here
  mean nothing. Use the menu → &ldquo;Open in Chrome&rdquo;, then start again.
</div>

<ul>${rowHtml}</ul>

<h2 style="font-size:16px">Result</h2>
<p class="lead">Copy this and send it back.</p>
<textarea id="summary" readonly></textarea>
<button id="copy">Copy result</button>

<script>
(function () {
  /**
   * In-app WebViews refuse custom schemes outright.
   *
   * This is the single largest source of false negatives in this test: a link
   * tapped inside a messaging app's built-in browser does nothing, which looks
   * IDENTICAL to the failure being investigated. Chrome's own Android WebView
   * marks itself with "; wv" in the user agent; the big messengers add their
   * own tokens. Neither check is exhaustive, so the banner warns rather than
   * blocks — a false warning costs a re-open, a missed one costs the run.
   */
  var ua = navigator.userAgent;
  var inWebView = /; wv\\)/.test(ua) || /FBAN|FBAV|Instagram|Line\\/|Twitter/i.test(ua);
  if (inWebView) document.getElementById('warn').classList.add('show');

  var results = {};

  /**
   * A UPI handoff reports neither success nor failure. The one observable
   * signal that an app took over is this page losing focus, so that is what is
   * watched — the same mechanism the real pay screen uses, kept deliberately
   * identical so this page tests the detection too and not just the links.
   *
   * 1600ms matches production. A slower threshold would catch sluggish app
   * starts, but every extra second is a second the tester spends staring at a
   * page that has already decided nothing happened.
   */
  function watch(id) {
    var handed = false;
    var mark = function () { handed = true; };
    var evs = [[document, 'visibilitychange'], [window, 'pagehide'], [window, 'blur']];
    evs.forEach(function (p) { p[0].addEventListener(p[1], mark); });
    setTimeout(function () {
      evs.forEach(function (p) { p[0].removeEventListener(p[1], mark); });
      var opened = handed || document.visibilityState === 'hidden';
      results[id] = opened ? 'opened' : 'nothing';
      var el = document.querySelector('[data-id="' + id + '"] [data-verdict]');
      el.textContent = opened
        ? 'something opened — which app? did it show a payee name?'
        : 'nothing happened';
      el.className = 'verdict ' + (opened ? 'opened' : 'nothing');
      render();
    }, 1600);
  }

  document.querySelectorAll('.row').forEach(function (row) {
    row.querySelector('.tap').addEventListener('click', function () { watch(row.dataset.id); });
  });

  function render() {
    var lines = ['ua: ' + ua, 'webview-detected: ' + inWebView, ''];
    document.querySelectorAll('.row').forEach(function (row) {
      var id = row.dataset.id;
      lines.push(id + ': ' + (results[id] || 'not tried'));
    });
    document.getElementById('summary').value = lines.join('\\n');
  }
  render();

  /**
   * The result is copied out by hand rather than beaconed anywhere.
   *
   * Silent reporting would be less trouble, but it would also collect less:
   * this page can only see whether it lost focus. WHICH app opened, whether a
   * chooser appeared, and whether the confirmation screen resolved a payee are
   * the observations that actually settle the question, and only the person
   * holding the phone can make them. So the page asks for them instead of
   * pretending focus-loss is the whole answer.
   */
  document.getElementById('copy').addEventListener('click', function () {
    var t = document.getElementById('summary');
    t.select();
    navigator.clipboard && navigator.clipboard.writeText(t.value);
  });
})();
</script>
`;
}

const [out] = process.argv.slice(2).filter((a) => !a.startsWith('--'));
if (out) {
  const arg = (name, dflt) => {
    const i = process.argv.indexOf(`--${name}`);
    return i === -1 ? dflt : process.argv[i + 1];
  };
  const vpa = arg('vpa', TEST_VPA);
  writeFileSync(out, renderPage({ vpa, payee: arg('payee', TEST_PAYEE) }));
  console.log(`wrote ${out}`);
  // Loud, because the unresolvable default and a real handle produce pages that
  // look identical and answer different questions.
  if (vpa === TEST_VPA) console.log('payee: UNRESOLVABLE DEFAULT — pass --vpa to test a resolving payee');
  else console.log(`payee: ${vpa} — a working link CAN move ₹${TEST_AMOUNT} from the tester`);
}
